head.script:
scwin.onpageload = function () {
    // 각 wframe scope 마다 자기 frame id 를 기록하여 상호 간섭 여부를 확인한다.
    scvar.VR_ctl_nm = $p.getFrameId();
    txt_info.setValue("scope=" + $p.getFrameId() + " / scvar.VR_ctl_nm=" + scvar.VR_ctl_nm);
    $p.top().scwin.log("[sub] " + $p.getFrameId() + " onpageload : scvar.VR_ctl_nm=" + scvar.VR_ctl_nm);
};
